/**
 * Финансы счёта гостя (DATA_MODEL §6, ADR-014: счёт на проживание). Деньги — только integer minor units (ADR-008).
 * Ни HTTP, ни Prisma: чистая арифметика и правила.
 */
export class FinanceRuleError extends Error {
  override readonly name = 'FinanceRuleError';
}

export interface FolioBalance {
  chargedMinor: bigint;
  paidMinor: bigint;
  refundedMinor: bigint;
  /** начислено − оплачено + возвращено; > 0 — гость должен, < 0 — переплата */
  balanceMinor: bigint;
}

export function folioBalance(input: {
  charges: Array<{ amountMinor: bigint; voided: boolean }>;
  allocations: Array<{ amountMinor: bigint }>;
  refunds: Array<{ amountMinor: bigint }>;
}): FolioBalance {
  const chargedMinor = input.charges
    .filter((c) => !c.voided)
    .reduce((s, c) => s + c.amountMinor, 0n);
  const paidMinor = input.allocations.reduce((s, a) => s + a.amountMinor, 0n);
  const refundedMinor = input.refunds.reduce((s, r) => s + r.amountMinor, 0n);
  return {
    chargedMinor,
    paidMinor,
    refundedMinor,
    balanceMinor: chargedMinor - paidMinor + refundedMinor,
  };
}

/** Платёж распределяется по счетам полностью, каждая строка > 0, счёт в платеже один раз. */
export function assertAllocationsMatch(
  amountMinor: bigint,
  allocations: Array<{ folioId: string; amountMinor: bigint }>,
): void {
  if (amountMinor <= 0n) throw new FinanceRuleError('Сумма платежа должна быть больше нуля');
  if (allocations.length === 0)
    throw new FinanceRuleError('Платёж должен быть распределён хотя бы на один счёт');
  const seen = new Set<string>();
  let sum = 0n;
  for (const a of allocations) {
    if (a.amountMinor <= 0n)
      throw new FinanceRuleError('Распределение на счёт должно быть больше нуля');
    if (seen.has(a.folioId))
      throw new FinanceRuleError(`Счёт ${a.folioId} встречается в платеже дважды`);
    seen.add(a.folioId);
    sum += a.amountMinor;
  }
  if (sum !== amountMinor)
    throw new FinanceRuleError(
      `Распределено ${sum}, а сумма платежа ${amountMinor} — должно совпадать`,
    );
}

/** Вернуть можно не больше, чем этот платёж внёс на этот счёт, минус уже возвращённое. */
export function assertRefundWithin(input: {
  allocatedMinor: bigint;
  refundedMinor: bigint;
  refundMinor: bigint;
}): void {
  if (input.refundMinor <= 0n) throw new FinanceRuleError('Сумма возврата должна быть больше нуля');
  const available = input.allocatedMinor - input.refundedMinor;
  if (input.refundMinor > available)
    throw new FinanceRuleError(
      `Вернуть можно не больше ${available} (внесено ${input.allocatedMinor}, уже возвращено ${input.refundedMinor})`,
    );
}

/** "15400", "456.23", "0,5", "-100.10" → minor units; не число или больше 2 знаков — ошибка. */
export function parseMoney(value: string): bigint {
  const m = /^(-)?(\d+)(?:[.,](\d{1,2}))?$/.exec(String(value).trim());
  if (!m)
    throw new FinanceRuleError(
      `Сумма «${value}» — число с не более чем двумя знаками после запятой`,
    );
  const minor = BigInt(m[2]!) * 100n + BigInt((m[3] ?? '').padEnd(2, '0'));
  return m[1] ? -minor : minor;
}

export type CancellationPenaltyPolicy = 'NONE' | 'FIRST_NIGHT' | 'FULL_STAY';

const CANCELLATION_PENALTIES: readonly CancellationPenaltyPolicy[] = [
  'NONE',
  'FIRST_NIGHT',
  'FULL_STAY',
];
/** Правило отмены из запроса (SET4, «Тарифные планы»): одно из трёх значений как есть, иначе `null` */
export function parseCancellationPenalty(v: unknown): CancellationPenaltyPolicy | null {
  return CANCELLATION_PENALTIES.find((p) => p === v) ?? null;
}

/**
 * Штраф при отмене / незаезде по политике тарифа (Q-103; правило объекта «штраф = стоимость первых суток»
 * привязано ко всем тарифам объекта). FIRST_NIGHT — цена первой ночи по календарю; календаря нет —
 * средняя ночь (цена / ночей, остаток отбрасывается). FULL_STAY — вся цена проживания. Отрицательного штрафа нет.
 */
export function penaltyAmount(
  policy: CancellationPenaltyPolicy,
  stay: { totalMinor: bigint; nights: number; firstNightMinor: bigint | null },
): bigint {
  if (policy === 'NONE' || stay.totalMinor <= 0n) return 0n;
  if (policy === 'FULL_STAY') return stay.totalMinor;
  if (stay.firstNightMinor !== null && stay.firstNightMinor > 0n) return stay.firstNightMinor;
  if (stay.nights <= 0) return 0n;
  return stay.totalMinor / BigInt(stay.nights);
}

/**
 * Наступил ли момент, когда штраф вообще взимается (Q-103, ответ управляющего 10.09.2026).
 *
 * Правило объекта: отмена заранее — бесплатно на всех каналах, штраф появляется только при отмене
 * в день заезда и позже. Незаезд считается всегда: место простояло. Сумма зависит от тарифа
 * (`penaltyAmount`), а этот признак отвечает только на вопрос «начислять ли вообще».
 *
 * Так работают Trip.com, Agoda и Expedia, где есть полная онлайн-оплата. На Booking предоплаты нет,
 * поэтому фактическое удержание там — ручное решение управляющего: система начисление поставит,
 * а стойка сторнирует его одной кнопкой, если списать не удалось.
 */
export function penaltyDue(input: {
  arrivalDate: string;
  /** Дата события в часах объекта (YYYY-MM-DD) */
  on: string;
  reason: 'cancel' | 'no_show';
}): boolean {
  if (input.reason === 'no_show') return true;
  return input.on >= input.arrivalDate;
}

/**
 * ADR-021: ранний заезд и поздний выезд — платные услуги на счёте проживания. Сумма по умолчанию —
 * половина цены одной ночи этого проживания, округление вниз до целого тенге (тиыны в сумме услуги
 * не нужны). Нет ночей или цены — 0: администратор задаёт сумму сам.
 */
export function stayExtraDefaultMinor(totalMinor: bigint, nights: number): bigint {
  if (nights <= 0 || totalMinor <= 0n) return 0n;
  const halfNight = totalMinor / BigInt(nights) / 2n;
  return (halfNight / 100n) * 100n;
}

/**
 * Настроенное правило объекта «Ранний заезд / Поздний выезд → Основное правило»:
 * привязано ко всем 6 тарифам). Расчётный час заезда 14:00, выезда 12:00.
 * Ранний заезд: 00:00–05:59 — 100 % цены ночи, 06:00–11:59 — 50 %, 12:00–13:59 — бесплатно.
 * Поздний выезд: 12:01–17:59 — 50 %, 18:00–23:59 — 100 %, до 12:00 — бесплатно.
 */
export function stayExtraPercent(
  extra: 'EARLY_CHECK_IN' | 'LATE_CHECK_OUT',
  time: string,
): 0 | 50 | 100 {
  const m = /^([01]\d|2[0-3]):([0-5]\d)$/.exec(time);
  if (!m) throw new Error(`время должно быть в формате ЧЧ:ММ, получено «${time}»`);
  const minutes = Number(m[1]) * 60 + Number(m[2]);
  if (extra === 'EARLY_CHECK_IN') {
    if (minutes < 6 * 60) return 100;
    if (minutes < 12 * 60) return 50;
    return 0;
  }
  if (minutes <= 12 * 60) return 0;
  if (minutes < 18 * 60) return 50;
  return 100;
}

/**
 * Соседняя ночь, которую занимает доплата: ранний заезд — ночь перед заездом, поздний выезд — ночь после
 * выезда. При обеих доплатах соседняя ночь на этой койке не продаётся.
 */
export function adjacentNight(
  extra: 'EARLY_CHECK_IN' | 'LATE_CHECK_OUT',
  arrivalDate: string,
  departureDate: string,
): { from: string; toExclusive: string } {
  const shift = (d: string, days: number) => {
    const x = new Date(`${d}T00:00:00Z`);
    x.setUTCDate(x.getUTCDate() + days);
    return x.toISOString().slice(0, 10);
  };
  return extra === 'EARLY_CHECK_IN'
    ? { from: shift(arrivalDate, -1), toExclusive: arrivalDate }
    : { from: departureDate, toExclusive: shift(departureDate, 1) };
}

/**
 * ADR-022 (Q-108): предоплата канала после отмены или незаезда. Деньги гостя держит площадка, поэтому
 * в PMS остаётся ровно та часть предоплаты, которая покрывает начисленный штраф, — её площадка
 * перечислит объекту. Остальное площадка возвращает гостю сама; без штрафа предоплата снимается целиком.
 */
export function channelPrepaymentToKeep(input: {
  prepaidMinor: bigint;
  penaltyMinor: bigint;
}): bigint {
  const penalty = input.penaltyMinor < 0n ? 0n : input.penaltyMinor;
  return penalty < input.prepaidMinor ? penalty : input.prepaidMinor;
}

/**
 * Аннулировать или заменить платёж (план `plans/finance-payments-direct-2026-10-07.md`, У3) можно, пока он
 * проведён, по нему нет возвратов и не выдан чек: возврат ссылается на платёж, а чек пробит на его сумму.
 * Прошлое не правится: ошибка аннулируется, нужная запись делается заново.
 */
export function assertPaymentReversible(input: {
  status: 'COMPLETED' | 'VOIDED';
  refundedMinor: bigint;
  receiptNumber: string | null;
}): void {
  if (input.status !== 'COMPLETED') throw new FinanceRuleError('Платёж уже аннулирован');
  if (input.refundedMinor > 0n)
    throw new FinanceRuleError(
      'По платежу есть возврат: аннулировать и менять его нельзя. Остаток верните возвратом',
    );
  if (input.receiptNumber)
    throw new FinanceRuleError(
      `По платежу выдан чек № ${input.receiptNumber}: аннулировать и менять его нельзя, оформите возврат`,
    );
}

/**
 * Скидка процентом (У7): доля базы целыми тиынами, остаток отбрасывается. База не положительная — 0:
 * скидка со знаком минус ни при каких данных не станет доплатой.
 */
export function discountMinor(baseMinor: bigint, percent: number): bigint {
  if (!Number.isInteger(percent) || percent < 0 || percent > 100)
    throw new FinanceRuleError('Процент скидки — целое число от 0 до 100');
  if (baseMinor <= 0n) return 0n;
  return (baseMinor * BigInt(percent)) / 100n;
}
