/**
 * Ручная бронь — чистые правила (plans/slice-3-step-3-4-manual-reservation.md).
 * Источники правил: DATA_MODEL §2 (статус на проживании, шапка производная), ADR-006, ADR-008.
 * Здесь нет ни HTTP, ни Prisma: только даты, статусы и деньги в minor units.
 */
import { dateRange } from '../chessboard/build';

export type ReservationStatus =
  'TENTATIVE' | 'CONFIRMED' | 'CHECKED_IN' | 'CHECKED_OUT' | 'CANCELLED' | 'NO_SHOW';

export type ReservationSource =
  'DESK' | 'PHONE' | 'WHATSAPP' | 'WALK_IN' | 'INSTAGRAM' | 'OTA' | 'WEBSITE';

export const RESERVATION_SOURCES: readonly ReservationSource[] = [
  'DESK',
  'PHONE',
  'WHATSAPP',
  'WALK_IN',
  'INSTAGRAM',
  'OTA',
  'WEBSITE',
];

export class ReservationRuleError extends Error {
  // тип string, а не литерал: подклассам нужно своё имя в логах
  override readonly name: string = 'ReservationRuleError';
}

/** Нарушение ограничения продаж (ADR-020): отдельный класс, чтобы API отдавал 409, а не 422. */
export class RestrictionViolationError extends ReservationRuleError {
  override readonly name: string = 'RestrictionViolationError';
}

export interface NightRate {
  date: string;
  occupancy: number;
  priceMinor: bigint;
}
export interface StayPrice {
  nights: Array<{ date: string; priceMinor: bigint }>;
  totalMinor: bigint;
}

const addDays = (iso: string, n: number): string => {
  const x = new Date(`${iso}T00:00:00Z`);
  x.setUTCDate(x.getUTCDate() + n);
  return x.toISOString().slice(0, 10);
};

/** Цена проживания = сумма DailyRate по ночам [arrival, departure) для нужного occupancy. Нет цены — ошибка. */
export function priceStay(input: {
  arrivalDate: string;
  departureDate: string;
  occupancy: number;
  rates: NightRate[];
}): StayPrice {
  if (input.departureDate <= input.arrivalDate)
    throw new ReservationRuleError(
      `Проживание должно содержать хотя бы одну ночь: заезд ${input.arrivalDate}, выезд ${input.departureDate}`,
    );
  const byDate = new Map(
    input.rates.filter((r) => r.occupancy === input.occupancy).map((r) => [r.date, r.priceMinor]),
  );
  const nights = dateRange(input.arrivalDate, addDays(input.departureDate, -1)).map((date) => {
    const priceMinor = byDate.get(date);
    if (priceMinor === undefined)
      throw new ReservationRuleError(`Нет цены на ночь ${date} (occupancy ${input.occupancy})`);
    return { date, priceMinor };
  });
  return { nights, totalMinor: nights.reduce((s, n) => s + n.priceMinor, 0n) };
}

const HEADER_PRIORITY: readonly ReservationStatus[] = [
  'CHECKED_IN',
  'CONFIRMED',
  'TENTATIVE',
  'CHECKED_OUT',
  'NO_SHOW',
];

/** Статус шапки из статусов проживаний (DATA_MODEL §2 v0.3). */
export function deriveReservationStatus(items: readonly ReservationStatus[]): ReservationStatus {
  if (items.length === 0) throw new ReservationRuleError('Бронь без проживаний');
  if (items.every((s) => s === 'CANCELLED')) return 'CANCELLED';
  for (const s of HEADER_PRIORITY) if (items.includes(s)) return s;
  return 'CANCELLED';
}

export function assertCanCancel(status: ReservationStatus): void {
  if (status === 'CANCELLED') throw new ReservationRuleError('Проживание уже отменено');
  if (status === 'CHECKED_IN')
    throw new ReservationRuleError('Гость заселён — отмена невозможна, нужен выезд');
  if (status !== 'TENTATIVE' && status !== 'CONFIRMED')
    throw new ReservationRuleError(`Отмена невозможна из статуса ${status}`);
}

export function assertCanChangeDates(status: ReservationStatus): void {
  if (status !== 'TENTATIVE' && status !== 'CONFIRMED')
    throw new ReservationRuleError(`Изменение дат невозможно из статуса ${status}`);
}

export function assertCanAssign(status: ReservationStatus): void {
  if (status !== 'TENTATIVE' && status !== 'CONFIRMED' && status !== 'CHECKED_IN')
    throw new ReservationRuleError(`Назначение ячейки невозможно из статуса ${status}`);
}

/** Заселение: ожидаемый гость и назначенная ячейка (DATA_MODEL §2: проживание = одна ячейка). */
export function assertCanCheckIn(status: ReservationStatus, hasUnit: boolean): void {
  if (status === 'CHECKED_IN') throw new ReservationRuleError('Гость уже заселён');
  if (status !== 'TENTATIVE' && status !== 'CONFIRMED')
    throw new ReservationRuleError(`Заселение невозможно из статуса ${status}`);
  if (!hasUnit) throw new ReservationRuleError('Сначала назначьте ячейку — заселить некуда');
}

/** Выезд только из заселённого проживания. */
export function assertCanCheckOut(status: ReservationStatus): void {
  if (status !== 'CHECKED_IN')
    throw new ReservationRuleError(`Выезд невозможен из статуса ${status}: гость не заселён`);
}

/** Незаезд: ожидаемый гость, который не приехал. */
export function assertCanNoShow(status: ReservationStatus): void {
  if (status !== 'TENTATIVE' && status !== 'CONFIRMED')
    throw new ReservationRuleError(`Незаезд невозможен из статуса ${status}`);
}

const ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';

/** `YYYYMMDD-XXXXXX`: дата создания в Asia/Almaty (UTC+5, без перехода на летнее время) + 6 символов. */
export function confirmationNumber(now: Date, random: () => number = Math.random): string {
  const almaty = new Date(now.getTime() + 5 * 3600 * 1000)
    .toISOString()
    .slice(0, 10)
    .replace(/-/g, '');
  let suffix = '';
  for (let i = 0; i < 6; i += 1)
    suffix += ALPHABET[Math.floor(random() * ALPHABET.length) % ALPHABET.length];
  return `${almaty}-${suffix}`;
}

/**
 * Продление проживания (T2). Заселённого продлевать можно: гость стоит у стойки и просит ещё ночь.
 * Выселенного, отменённого и незаезд — нет: там проживание уже закончено.
 */
export function assertCanExtend(status: ReservationStatus): void {
  if (status !== 'TENTATIVE' && status !== 'CONFIRMED' && status !== 'CHECKED_IN')
    throw new ReservationRuleError(`Продление невозможно из статуса ${status}`);
}

/** Строка Restriction на дату × категория × тариф (DATA_MODEL §4). Нет строки = нет ограничений. */
export interface StayRestriction {
  date: string;
  minStay: number | null;
  maxStay: number | null;
  stopSell: boolean;
  closedToArrival: boolean;
  closedToDeparture: boolean;
}

/**
 * ADR-020: ограничения продаж действуют и на стойке, отказ — с названием ограничения, датой и категорией.
 *  — стоп-продажа на любую ночь проживания [arrival, departure);
 *  — закрыт заезд — на дату заезда; закрыт выезд — на дату выезда;
 *  — минимальный и максимальный срок — по дате заезда, сравнивается с длиной проживания.
 * `soldUntil` — продление: ночи до этой даты уже проданы, стоп-продажу, закрытый заезд и минимум срока
 * на них не перепроверяем (гость уже живёт), а добавленные ночи, выезд и максимум срока — да.
 */
export function assertRestrictionsAllow(input: {
  arrivalDate: string;
  departureDate: string;
  categoryName: string;
  restrictions: readonly StayRestriction[];
  soldUntil?: string | undefined;
}): void {
  if (input.departureDate <= input.arrivalDate)
    throw new ReservationRuleError(
      `Проживание должно содержать хотя бы одну ночь: заезд ${input.arrivalDate}, выезд ${input.departureDate}`,
    );
  const byDate = new Map(input.restrictions.map((r) => [r.date, r]));
  const where = (date: string) => `на ${date}, ${input.categoryName}`;
  const nights = dateRange(input.arrivalDate, addDays(input.departureDate, -1)).length;
  const newStay = input.soldUntil === undefined;
  const firstUnsold =
    input.soldUntil && input.soldUntil > input.arrivalDate ? input.soldUntil : input.arrivalDate;

  const arrival = byDate.get(input.arrivalDate);
  if (newStay && arrival?.closedToArrival)
    throw new RestrictionViolationError(`Закрыт заезд ${where(input.arrivalDate)}`);
  if (newStay && arrival?.minStay != null && nights < arrival.minStay)
    throw new RestrictionViolationError(
      `Минимальный срок ${arrival.minStay} ноч. ${where(input.arrivalDate)}: запрошено ${nights} ноч.`,
    );
  if (arrival?.maxStay != null && nights > arrival.maxStay)
    throw new RestrictionViolationError(
      `Максимальный срок ${arrival.maxStay} ноч. ${where(input.arrivalDate)}: запрошено ${nights} ноч.`,
    );
  if (firstUnsold < input.departureDate)
    for (const date of dateRange(firstUnsold, addDays(input.departureDate, -1)))
      if (byDate.get(date)?.stopSell)
        throw new RestrictionViolationError(`Стоп-продажа ${where(date)}`);
  if (byDate.get(input.departureDate)?.closedToDeparture)
    throw new RestrictionViolationError(`Закрыт выезд ${where(input.departureDate)}`);
}
